n\nfunc assertFlagValue(t *testing.T, args []string, flag, want string) {\n\tt.Helper()\n\tif got := flagValue(args, flag); got != want {\n\t\tt.Fatalf(\"%s = %q, want %q in %#v\", flag, got, want, args)\n\t}\n}\n\nfunc waitForInvocations(t *testing.T, path string, want int) {\n\tt.Helper()\n\tdeadline := time.Now().Add(3 * time.Second)\n\tfor time.Now().Before(deadline) {\n\t\tif raw, err := os.ReadFile(path); err == nil {\n\t\t\ttrimmed := strings.TrimSpace(string(raw))\n\t\t\tif trimmed != \"\" \u0026\u0026 strings.Count(trimmed, \"\\n\")+1 \u003e= want {\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t\ttime.Sleep(10 * time.Millisecond)\n\t}\n\tt.Fatalf(\"timed out waiting for %d invocation(s)\", want)\n}\n","replaceAll":false,"structuredPatch":[{"lines":[" "," func TestIsArtifactPathError(t *testing.T) {","   agyMessage := \"declaring permissions: cortex tool write_to_file: convert tool call for permissions: model output error: invalid tool call error (invalid_args) /workdir/gemini_proposal.md is not a valid artifact path; artifacts must be in /Users/tyler/.gemini/antigravity-cli/brain/56536675-0470-4bfc-b8ee-a04946debce9/\"","+  hookMessage := \"tool call denied by pre-tool hook: \" + nativeWriteHookMarker + \" Native write_to_file, replace_file_content, and multi_replace_file_content are disabled: ...\"","   for _, tc := range []struct {","     name string","     err  *harness.Error"],"newLines":7,"newStart":150,"oldLines":6,"oldStart":150},{"lines":["   }{","     {\"nil error\", nil, false},","     {\"agy artifact-path error\", \u0026harness.Error{Category: harness.ErrorTerminal, Message: agyMessage}, true},","+    {\"tractor native-write hook denial\", \u0026harness.Error{Category: harness.ErrorTerminal, Message: hookMessage}, true},","     {\"unrelated terminal error\", \u0026harness.Error{Category: harness.ErrorTerminal, Message: \"unknown model x\"}, false},","   } {","     t.Run(tc.name, func(t *testing.T) {"],"newLines":7,"newStart":158,"oldLines":6,"oldStart":157}