    11	
    12	// nativeWriteTools are agy's native tools capable of mutating files
    13	// in-process. Google's Hooks tool reference documents write_to_file and
    14	// multi_replace_file_content as able to carry ArtifactMetadata against the
    15	// call's target path; replace_file_content is grouped with them as the
    16	// third native file-mutating operation. A call to any of the three whose
    17	// target lies outside agy's private per-conversation
    18	// ~/.gemini/antigravity-cli/brain/<uuid>/ directory fails the whole turn
    19	// with "is not a valid artifact path" — see isArtifactPathError in
    20	// adapter.go and ephemeral/worklog/20260819-agy-artifact-prevention.md for
    21	// the full failure mechanism.
    22	//
    23	// Google documents a custom agent's `tools:` frontmatter allowlist,
    24	// selected via `agy --agent <name>`, as the way to remove these tools from
    25	// an agent's toolset. Empirical testing against real agy 1.1.15
    26	// (see the worklog) disproves this for a --agent-selected mainAgent:
    27	// init.tools reports the full tool set regardless of the manifest's
    28	// tools: content — including with a single-tool allowlist — and an
    29	// explicitly-excluded write_to_file remains fully callable and reproduces
    30	// the exact bug. Tractor therefore does not provision a custom agent or
    31	// pass --agent; ensureNativeWriteHook below is the mechanism verified to
    32	// actually intercept these calls.
    33	var nativeWriteTools = []string{
    34		"write_to_file",
    35		"replace_file_content",
    36		"multi_replace_file_content",
    37	}
    38	
    39	// tractorHookName is the top-level key Tractor owns inside agy's global
    40	// hooks.json. ensureNativeWriteHook only ever reads or writes this one
    41	// key, leaving any other hooks the user or another tool has configured
    42	// alone.
    43	const tractorHookName = "tractor-no-native-write"
    44	
    45	// nativeWriteHookMarker is embedded in the hook's deny reason. It lets
    46	// ensureNativeWriteHook tell a stale/older Tractor-authored entry (safe to
    47	// overwrite with the current content) apart from a same-named hook a user
    48	// configured independently (refuse to clobber), and lets isArtifactPathError
    49	// in adapter.go recognize the hook's own denial as the same recoverable
    50	// failure class as agy's native artifact-path error.
    51	const nativeWriteHookMarker = "[tractor-no-native-write]"
    52	
    53	func hooksConfigPath(homeDir string) string {
    54		return filepath.Join(homeDir, ".gemini", "config", "hooks.json")
    55	}
    56	
    57	type hookHandler struct {
    58		Command string `json:"command"`
    59		Timeout int    `json:"timeout"`
    60	}
    61	
    62	type hookGroup struct {
    63		Matcher string        `json:"matcher"`
    64		Hooks   []hookHandler `json:"hooks"`
    65	}
    66	
    67	type hookSpec struct {
    68		PreToolUse []hookGroup `json:"PreToolUse"`
    69	}
    70	
    71	// nativeWriteHookSpec builds the PreToolUse hook entry that hard-blocks
    72	// nativeWriteTools before agy executes them. The handler is a single
    73	// inline shell command (no separate script file to provision or clean up):
    74	// it discards agy's hook-context stdin payload and prints the required
    75	// {"decision":"deny","reason":"..."} JSON contract on stdout. Verified
    76	// live against agy 1.1.15: the denied call never reaches the filesystem,
    77	// and the model recovers by calling run_command instead.
    78	func nativeWriteHookSpec() hookSpec {
    79		reason := nativeWriteHookMarker + " Native write_to_file, replace_file_content, and multi_replace_file_content are disabled: agy fails the whole turn when their target lies outside the private brain/<uuid> directory even though the physical write already succeeded. Use run_command for all workspace file writes instead."
    80		var buf bytes.Buffer
    81		encoder := json.NewEncoder(&buf)
    82		encoder.SetEscapeHTML(false)
    83		if err := encoder.Encode(map[string]string{"decision": "deny", "reason": reason}); err != nil {
    84			panic(fmt.Sprintf("agy: encode native-write hook denial: %v", err))
    85		}
    86		denyJSON := strings.TrimSpace(buf.String())
    87		command := "cat >/dev/null; printf '%s\\n' '" + denyJSON + "'"
    88		return hookSpec{
    89			PreToolUse: []hookGroup{
    90				{
    91					Matcher: strings.Join(nativeWriteTools, "|"),
    92					Hooks:   []hookHandler{{Command: command, Timeout: 5}},
    93				},
    94			},
    95		}
    96	}
    97	
    98	// ensureNativeWriteHook idempotently provisions Tractor's PreToolUse deny
    99	// hook under homeDir's global agy hooks.json, merging with (not replacing)
   100	// any other hooks already configured there.
   101	//
   102	// Global placement is deliberate, unlike a workspace-local
   103	// .agents/hooks.json: Tractor's isolated-worktree branches each get their
   104	// own workdir (engine/artifacts.go, added in 2485e4c), so a workspace-local
   105	// hook would need provisioning into and cleanup from every branch worktree,
   106	// and a leftover file would show up in that branch's git status and be
   107	// swept into artifact collection — exactly what this fix must not do. A
   108	// single global hooks.json, provisioned once, avoids both problems. It also
   109	// benefits the user's own interactive agy sessions: the underlying bug
   110	// (native write succeeds, then the turn fails declaring it as an artifact)
   111	// is not print-mode-specific, so blocking it globally fixes the same
   112	// failure for manual `agy --add-dir <workspace>` usage too.
   113	func ensureNativeWriteHook(homeDir string) error {
   114		path := hooksConfigPath(homeDir)
   115		canonical, err := json.Marshal(nativeWriteHookSpec())
   116		if err != nil {
   117			return fmt.Errorf("encode tractor native-write hook: %w", err)
   118		}
   119	
   120		raw, readErr := os.ReadFile(path)
   121		doc := map[string]json.RawMessage{}
   122		switch {
   123		case readErr == nil:
   124			if err := json.Unmarshal(raw, &doc); err != nil {
   125				return fmt.Errorf("parse %s: %w (fix or remove the file so Tractor can add its hook)", path, err)
   126			}
   127		case os.IsNotExist(readErr):
   128			// doc stays empty; created below.
   129		default:
   130			return fmt.Errorf("read %s: %w", path, readErr)
   131		}
   132	
   133		if existing, ok := doc[tractorHookName]; ok {
   134			if bytes.Equal(bytes.TrimSpace(existing), canonical) {
   135				return nil
   136			}
   137			if !strings.Contains(string(existing), nativeWriteHookMarker) {
   138				return fmt.Errorf(
   139					"%s already has a %q hook that is not Tractor-managed (missing marker comment in its reason text); "+
   140						"remove it or rename Tractor's hook (harness/agy.tractorHookName) to avoid clobbering it",
   141					path, tractorHookName,
   142				)
   143			}
   144			// A stale Tractor-authored entry (e.g. an older reason string);
   145			// fall through and overwrite it with current content.
   146		}
   147	
   148		doc[tractorHookName] = canonical
   149		encoded, err := json.MarshalIndent(doc, "", "  ")
   150		if err != nil {
   151			return fmt.Errorf("encode %s: %w", path, err)
   152		}
   153		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
   154			return fmt.Errorf("create %s: %w", filepath.Dir(path), err)
   155		}
   156		if err := os.WriteFile(path, append(encoded, '\n'), 0o644); err != nil {
   157			return fmt.Errorf("write %s: %w", path, err)
   158		}
   159		return nil
   160	}
