   302	// Close interrupts all active agy processes.
   303	func (a *Adapter) Close() {
   304		a.mu.Lock()
   305		if a.closed {
   306			a.mu.Unlock()
   307			return
   308		}
   309		a.closed = true
   310		states := make([]*sessionState, 0, len(a.states))
   311		for _, state := range a.states {
   312			states = append(states, state)
   313		}
   314		a.mu.Unlock()
   315		for _, state := range states {
   316			state.mu.Lock()
   317			active := state.active
   318			state.mu.Unlock()
   319			if active != nil {
   320				interruptProcess(active)
   321			}
   322		}
   323	}
