   325	// ensureHook provisions (once per Adapter) the Tractor-owned PreToolUse
   326	// deny hook that blocks agy's native write tools before they execute. See
   327	// native_write_hook.go for why this — not the documented custom-agent
   328	// tools: allowlist — is the mechanism Tractor actually uses.
   329	func (a *Adapter) ensureHook() *harness.Error {
   330		a.hookOnce.Do(func() {
   331			home := a.config.homeDir
   332			if home == "" {
   333				resolved, err := os.UserHomeDir()
   334				if err != nil {
   335					a.hookErr = terminal(fmt.Sprintf("resolve home directory for agy native-write hook: %v", err))
   336					return
   337				}
   338				home = resolved
   339			}
   340			if err := ensureNativeWriteHook(home); err != nil {
   341				a.hookErr = terminal(fmt.Sprintf("provision tractor agy native-write hook: %v", err))
   342				return
   343			}
   344		})
   345		return a.hookErr
   346	}
