   348	func (a *Adapter) runForState(state *sessionState, request runRequest) (nativeResult, *activeTurn, *harness.Error) {
   349		result, active, err := a.runOnceWithActive(request, func(active *activeTurn) {
   350			state.mu.Lock()
   351			state.active = active
   352			state.mu.Unlock()
   353		})
   354		state.mu.Lock()
   355		if state.active == active {
   356			state.active = nil
   357		}
   358		state.mu.Unlock()
   359		return result, active, err
   360	}
