   362	func (a *Adapter) runWithSteering(
   363		state *sessionState,
   364		request runRequest,
   365		deadline time.Time,
   366		originalTimeout time.Duration,
   367	) (nativeResult, *activeTurn, *harness.Error) {
   368		for {
   369			result, active, err := a.runForState(state, request)
   370			parts := takeSteer(state)
   371			if len(parts) == 0 {
   372				return result, active, err
   373			}
   374			if err != nil && (active == nil || !active.steered.Load() || err.Category != harness.ErrorInterrupted) {
   375				return nativeResult{}, active, err
   376			}
   377			request.projector.user(parts)
   378			request.prompt = joinParts(parts)
   379			request.timeout = remaining(deadline, originalTimeout)
   380			if request.timeout <= 0 && originalTimeout > 0 {
   381				return nativeResult{}, active, interrupted("turn timed out and was interrupted")
   382			}
   383		}
   384	}
   385	
   386	func takeSteer(state *sessionState) []harness.ContentPart {
   387		state.mu.Lock()
   388		defer state.mu.Unlock()
   389		if len(state.pendingSteer) == 0 {
   390			return nil
   391		}
   392		parts := state.pendingSteer[0]
   393		state.pendingSteer = state.pendingSteer[1:]
   394		return parts
   395	}
