   741	// artifactPathErrorMarker matches agy's own error text when the model's
   742	// file-write tool call is routed through agy's native artifact tool, which
   743	// only accepts paths inside its private per-conversation "brain" directory
   744	// and rejects any path inside the workspace agy was given via --add-dir.
   745	// This is the fallback signature: the ensureHook-provisioned PreToolUse
   746	// hook (native_write_hook.go) blocks the tool before agy ever reaches this
   747	// declare-permissions failure, but the hook itself can only be as reliable
   748	// as agy's hooks.json support, so this detector stays in place in case the
   749	// hook is ever bypassed (e.g. a workspace with its own conflicting hook, or
   750	// a future agy version that stops honoring it).
   751	const artifactPathErrorMarker = "is not a valid artifact path"
   752	
   753	// isArtifactPathError reports whether err is agy's "declaring permissions"
   754	// failure for a file-write tool call targeting a path outside its brain
   755	// directory (agy's own error text), or Tractor's own PreToolUse hook denial
   756	// of the same class of call (nativeWriteHookMarker, native_write_hook.go).
   757	// Either way the fix is identical: redo the turn's writes via run_command.
   758	func isArtifactPathError(err *harness.Error) bool {
   759		if err == nil {
   760			return false
   761		}
   762		return strings.Contains(err.Message, artifactPathErrorMarker) || strings.Contains(err.Message, nativeWriteHookMarker)
